using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using System.IO;
using UnityEngine;
using UnityEngine.EventSystems;
using Newtonsoft.Json.Linq;
using TMPro;
using IslandGame;
public static class ValidatePoker {
 static readonly List<string> checks=new List<string>();
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);checks.Add(message);}
 static void Set(IslandApp a,string field,object value)=>typeof(IslandApp).GetField(field,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(a,value);
 static JObject State(int count=6,bool turn=true){var seats=new JArray();for(int i=0;i<count;i++)seats.Add(new JObject{{"seatId",i},{"name","플레이어 "+i},{"portrait",i+1},{"isMe",i==0},{"stack",5000},{"currentBet",0},{"inHand",true},{"folded",false},{"holeCards",new JArray(i==0?"A♠":"??",i==0?"K♥":"??")}});long now=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();return new JObject{{"preAction",JValue.CreateNull()},{"tournament",JValue.CreateNull()},{"dealStage",JValue.CreateNull()},{"winnerInfo",JValue.CreateNull()},{"handNumber",1},{"phase","PREFLOP"},{"mySeatId",0},{"activeSeatId",turn?0:1},{"seats",seats},{"boardCards",new JArray("2♠","3♥","4♦")},{"totalPot",1000},{"callAmount",200},{"minRaise",400},{"maxRaise",5000},{"isUserTurn",turn},{"serverNow",now},{"actionDeadline",now+10000},{"buttonSeat",3},{"smallBlindSeat",4},{"bigBlindSeat",5}};}
 static UnityEngine.UI.Button Button(string name)=>UnityEngine.Object.FindObjectsByType<UnityEngine.UI.Button>(FindObjectsSortMode.None).First(b=>b.name==name);
 static void Bind(IslandApp a,IslandPokerHud hud,JObject state,string page="poker6"){Set(a,"page",page);Set(a,"online",true);Set(a,"table",state);Set(a,"pokerReceivedAt",Time.unscaledTime);hud.SendMessage("Update");Canvas.ForceUpdateCanvases();}
 public static object Main(){
  checks.Clear();var a=UnityEngine.Object.FindFirstObjectByType<IslandApp>();var hud=a.GetComponent<IslandPokerHud>();var actual=a.PokerState;if(actual==null)throw new Exception("Join local real server first");
  if(!File.Exists("C:/Users/SHK/island-poker-review/real-server-snapshot.json"))File.WriteAllText("C:/Users/SHK/island-poker-review/real-server-snapshot.json",actual.ToString());a.GetComponent<PollingSocket>().Close();var s=State();Bind(a,hud,s);hud.GetComponentsInChildren<RectTransform>(true).First(r=>r.name=="PokerBetMenu").gameObject.SetActive(false);
  Check(hud.Visible,"Native poker Canvas visible");Check(UnityEngine.Object.FindObjectsByType<EventSystem>(FindObjectsSortMode.None).Length==1,"Exactly one EventSystem");
  var surface=UnityEngine.Object.FindFirstObjectByType<IslandPokerTableSurface>();Check(surface.canvasRenderer.GetMesh()?.vertexCount>0,"Table procedural graphic renders");
  foreach(var t in hud.GetComponentsInChildren<TextMeshProUGUI>())if(t.name=="PlayerName"||t.name=="PlayerStack"){t.ForceMeshUpdate();Check(t.textInfo.characterInfo.Take(t.textInfo.characterCount).Any(c=>c.isVisible),t.name+" is readable");}
  foreach(var b in hud.GetComponentsInChildren<UnityEngine.UI.Button>()){var corners=new Vector3[4];((RectTransform)b.transform).GetWorldCorners(corners);Check(corners.All(p=>{var v=RectTransformUtility.WorldToScreenPoint(null,p);return v.x>=Screen.safeArea.xMin-1&&v.x<=Screen.safeArea.xMax+1&&v.y>=Screen.safeArea.yMin-1&&v.y<=Screen.safeArea.yMax+1;}),b.name+" fits SafeArea");}
  Check(Button("PokerFold").interactable&&Button("PokerCall").interactable,"Legal turn actions enabled");Button("PokerPotMenu").onClick.Invoke();Check(!Button("PotFraction2").interactable,"Below-minimum quarter-pot disabled");Check(Button("PotFraction0").interactable&&Button("PotFraction1").interactable,"Legal pot fractions enabled");
  var input=UnityEngine.Object.FindFirstObjectByType<TMP_InputField>();input.text="100.5";Check(!Button("SubmitCustomRaise").interactable,"Fractional cash chip input rejected");input.text="500";Check(Button("SubmitCustomRaise").interactable,"Legal exact custom street total accepted");
  int before=hud.ActionDispatches;var fold=Button("PokerFold");fold.onClick.Invoke();fold.onClick.Invoke();Check(hud.ActionDispatches==before+1&&hud.ActionPending,"Duplicate action blocked until server state changes");
  var next=(JObject)s.DeepClone();next["handNumber"]=2;Bind(a,hud,next);Check(!hud.ActionPending,"New server context unlocks controls");
  var off=State(6,false);Bind(a,hud,off);Check(!Button("PokerFold").interactable&&!Button("PokerCall").interactable,"Off-turn actions disabled");
  var full=State(8);full["tournament"]=new JObject{{"bigBlind",200}};Bind(a,hud,full,"pokerTournament");Check(hud.GetComponentsInChildren<RectTransform>().Count(r=>r.name.StartsWith("PokerSeat"))==8,"Eight-player tournament positions bound");Button("PokerPotMenu").onClick.Invoke();input.text="2.5";Check(Button("SubmitCustomRaise").interactable,"BB decimal input resolves to integer chip total");
  var unknown=hud.GetComponentsInChildren<TextMeshProUGUI>().Where(t=>t.name=="Rank"&&t.transform.parent.name.StartsWith("Hole")).ToArray();Check(unknown.Count(t=>!string.IsNullOrEmpty(t.text))==2,"Other players remain server-masked");
  var show=State();show["phase"]="SHOWDOWN";show["boardCards"]=new JArray("2♠","3♥","4♦","5♣","6♠");show["showdownHands"]=new JArray(new JObject{{"seatId",0},{"name","플레이어 0"},{"handCategory","스트레이트"},{"isWinner",true}},new JObject{{"seatId",1},{"name","플레이어 1"},{"handCategory","스트레이트"},{"isWinner",true}});Bind(a,hud,show);Check(GameObject.Find("ShowdownResults")!=null,"Showdown result panel shown");Check(hud.GetComponentsInChildren<CanvasGroup>().Count(c=>c.alpha<.5f)==2,"Best five cards emphasized from publicly revealed data");
  Bind(a,hud,State());var callRect=(RectTransform)Button("PokerCall").transform;var screen=RectTransformUtility.WorldToScreenPoint(null,callRect.TransformPoint(callRect.rect.center));var pointer=new PointerEventData(EventSystem.current){position=screen};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(pointer,hits);Check(hits.Count>0&&hits[0].gameObject==Button("PokerCall").gameObject,"uGUI touch raycast reaches call button");var audio=a.PokerAudio;bool originalMute=audio.Muted;audio.SetMuted(false);audio.BeginTable();Check(audio.TrackName=="lobby_jazz"&&Mathf.Abs(audio.MusicVolume-.06f)<.001f,"Web table BGM and gain");int n=audio.EffectEvents;audio.DealStage("shuffle","test1");Check(audio.ShufflePlaying,"Shuffle loops during clear interval");audio.DealStage("cards","test1");Check(!audio.ShufflePlaying&&audio.LastEffect=="taking_card","Deal stops shuffle and plays card sound");audio.DealStage("cards","test1");Check(audio.EffectEvents==n+2,"Repeated snapshot does not replay deal sounds");audio.SetMuted(true);n=audio.EffectEvents;audio.PlayerAction("raise");Check(!audio.MusicPlaying&&audio.EffectEvents==n,"Muted audio suppresses BGM and effects");audio.SetMuted(false);audio.PlayerAction("all-in");Check(audio.LastEffect=="all_in_chip","All-in event sound normalized");audio.EndTable();Check(Mathf.Abs(audio.MusicVolume-.24f)<.001f,"Lobby music gain restored");audio.SetMuted(originalMute);audio.BeginTable();
  var report=new{status="PASS",resolution=Screen.width+"x"+Screen.height,count=checks.Count,checks};File.WriteAllText("C:/Users/SHK/island-poker-review/validation-"+Screen.width+"x"+Screen.height+".json",Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented));return report;
 }
 public static object Meshes(){int triangles=0;foreach(var type in new[]{PrimitiveType.Cube,PrimitiveType.Cylinder,PrimitiveType.Sphere,PrimitiveType.Quad}){var mesh=IslandDisplayMeshes.Create(type);var v=mesh.vertices;var normals=mesh.normals;var idx=mesh.triangles;for(int i=0;i<idx.Length;i+=3){var cross=Vector3.Cross(v[idx[i+1]]-v[idx[i]],v[idx[i+2]]-v[idx[i]]);if(cross.sqrMagnitude>1e-10f&&Vector3.Dot(cross,normals[idx[i]])<0)throw new Exception("Backface "+type);triangles++;}var size=mesh.bounds.size;if(Vector3.Distance(size,type==PrimitiveType.Cylinder?new Vector3(1,2,1):type==PrimitiveType.Quad?new Vector3(1,1,0):Vector3.one)>.001f)throw new Exception("Bounds "+type);UnityEngine.Object.DestroyImmediate(mesh);}return new{status="PASS",types=4,triangles};}
}
